import { BottomSheet, FOOTER_ACTIONS_ORIENTATION } from '@ds/bottom-sheet';
import { extractSupportProps } from '@ds/utils';

import { DrawerProps } from '../../components/Drawer/types';
import { TEST_IDS } from '../../constants';

/**
 * Mobile-поверхность Drawer'а: контент в `BottomSheet`, слоты маппятся на API sheet'а
 * (`subtitle` 1:1, `showBlackout→showBackdrop`, остальное 1:1). Internal. Desktop-only пропы
 * уходят в `...rest`.
 */
export function MobileDrawer({
  content,
  media,
  title,
  slotAfterTitle,
  slotSecondTitle,
  subtitle,
  onBackButtonClick,
  approveButton,
  cancelButton,
  additionalButton,
  footerActionsOrientation = FOOTER_ACTIONS_ORIENTATION.Vertical,
  footer,
  className,
  rootClassName,
  open,
  onClose,
  showBlackout,
  lockScroll,
  container,
  closeOnPopstate,
  swipeEnabled,
  snapPoints,
  snapIndex,
  onSnapIndexChange,
  safeAreaTop,
  safeAreaBottom,
  withDividers = false,
  ...rest
}: DrawerProps) {
  // Футер собирает сам `BottomSheet`.
  return (
    <BottomSheet
      // Дефолт `withDividers` в sheet'е — `true`; у Drawer'а вид исторически без разделителей.
      withDividers={withDividers}
      open={open}
      onClose={onClose}
      showBackdrop={showBlackout}
      lockScroll={lockScroll}
      title={title}
      subtitle={subtitle}
      slotAfterTitle={slotAfterTitle}
      slotSecondTitle={slotSecondTitle}
      onBackButtonClick={onBackButtonClick}
      media={media}
      content={content}
      approveButton={approveButton}
      cancelButton={cancelButton}
      additionalButton={additionalButton}
      footerActionsOrientation={footerActionsOrientation}
      footer={footer}
      // Те же id футера, что у desktop-поверхности — стабильный селектор при свапе surface.
      footerTestIds={{
        approve: TEST_IDS.footerApprove,
        cancel: TEST_IDS.footerCancel,
        additional: TEST_IDS.footerAdditional,
      }}
      className={className}
      rootClassName={rootClassName}
      container={container}
      closeOnPopstate={closeOnPopstate}
      swipeEnabled={swipeEnabled}
      snapPoints={snapPoints}
      snapIndex={snapIndex}
      onSnapIndexChange={onSnapIndexChange}
      safeAreaTop={safeAreaTop}
      safeAreaBottom={safeAreaBottom}
      {...extractSupportProps(rest)}
    />
  );
}
